// Purpose: bundle the gh-pages review-tambor demo (wanna-8ay)
// Responsibilities: esbuild page/review-tambor/main.ts (plus its tambor and
//   wanna source imports) into page/review-tambor/main.js — one self-contained
//   ESM bundle the static index.html loads; the artifact is gitignored
//   (regenerated by CI on deploy) so the repo carries only sources
// Rationale: the build-dist.mjs precedent (esbuild, dev-only dep; bin/esbuild
//   is a native binary — invoked directly, not through node). The .js bundle
//   is derived state: a stale committed bundle would drift from the sources.
import { execFileSync } from "node:child_process";
import path from "node:path";
import { fileURLToPath } from "node:url";

const repo = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const esbuild = path.join(repo, "node_modules/esbuild/bin/esbuild");
const out = path.join(repo, "page/review-tambor/main.js");

execFileSync(
  esbuild,
  [
    path.join(repo, "page/review-tambor/main.ts"),
    "--bundle",
    "--format=esm",
    "--target=es2022",
    "--platform=browser",
    `--outfile=${out}`,
    "--log-level=info",
  ],
  { stdio: "inherit" },
);
console.log(`built ${path.relative(repo, out)}`);
